import 'dart:convert';
import 'dart:io';
import 'package:analyzer/dart/analysis/utilities.dart';

/// Generates only stable message identifiers and typed gen_l10n dispatch.
/// There is deliberately no English-source matching in generated runtime code.
void main(List<String> arguments) {
  final arb =
      jsonDecode(File('lib/l10n/app_en.arb').readAsStringSync())
          as Map<String, dynamic>;
  final keys = arb.keys.where((k) => !k.startsWith('@')).toList()..sort();
  final codes = StringBuffer(
    "// GENERATED by tool/generate_message_codes.dart.\nimport 'dart:convert';\nString encodeMessage(String key,List<Object?> arguments)=>'@l10n/\$key|\${jsonEncode(arguments)}';\nabstract final class MessageCode {\n",
  );
  final resolver = StringBuffer(
    "// GENERATED by tool/generate_message_codes.dart.\nimport '../../l10n/app_localizations.dart';\nimport '../constants/app_brand.dart';\nimport 'app_l10n.dart' show resolveMessage;\nString resolveTypedMessage(AppLocalizations l,String key,List<dynamic> args){\nString text(int i)=>i<args.length?resolveMessage(l,args[i].toString()):'';\nint number(int i)=>int.parse(args[i].toString());\nreturn switch(key){\n",
  );
  for (final key in keys) {
    final placeholders = Map<String, dynamic>.from(
      (arb['@$key'] as Map?)?['placeholders'] as Map? ?? {},
    );
    final parameters = placeholders.entries
        .where((e) => e.key != 'brandName')
        .toList();
    if (parameters.isEmpty) {
      codes.writeln("static const $key='@l10n/$key';");
    } else {
      codes.writeln(
        "static String $key(${parameters.map((p) => '${p.value['type'] ?? 'String'} ${p.key}').join(',')})=>encodeMessage('$key',[${parameters.map((p) => p.key).join(',')}]);",
      );
    }
    var index = 0;
    final arguments = placeholders.entries.map((p) {
      if (p.key == 'brandName') return 'AppBrand.name';
      final i = index++;
      return p.value['type'] == 'int' ? 'number($i)' : 'text($i)';
    }).toList();
    resolver.writeln(
      "'$key'=>l.$key${arguments.isEmpty ? '' : '(${arguments.join(',')})'},",
    );
  }
  codes.writeln('}');
  resolver.writeln("_=>l.updateRequired,};}\n");
  final outputs = {
    'lib/core/l10n/message_codes.g.dart': codes.toString(),
    'lib/core/l10n/message_resolver.g.dart': resolver.toString(),
  };
  for (final entry in outputs.entries) {
    final file = File(entry.key);
    if (arguments.contains('--check')) {
      if (!file.existsSync() ||
          parseString(content: file.readAsStringSync()).unit.toSource() !=
              parseString(content: entry.value).unit.toSource()) {
        stderr.writeln('STALE_MESSAGE_GENERATION ${entry.key}');
        exitCode = 1;
      }
    } else {
      file.writeAsStringSync(entry.value);
    }
  }
  stdout.writeln(
    '${arguments.contains('--check') ? 'MESSAGE_CODES_CHECKED' : 'MESSAGE_CODES_GENERATED'} keys=${keys.length} exit=$exitCode',
  );
}
